    pub unsafe fn data_ptr(&self) -> *mut u8 {
        self.lock_ptr as _
    }

    pub fn width(&self) -> u32 {
        self.input_buffer.width
    }

    pub fn height(&self) -> u32 {
        self.input_buffer.height
    }

