//! Windows input injection through `SendInput`.
//!
//! Protocol v3 keeps the existing macOS `NSEvent.keyCode` values on the wire.
//! This module mirrors that physical-key table to Windows virtual-key values,
//! maps the v3 modifier bits (Option -> Alt, Command -> Windows), and supports
//! normalized absolute pointer motion, relative motion, buttons, and scrolling.
//!
//! CI validates the bindings and pure mapping tests. Runtime QA must confirm
//! behavior across keyboard layouts, mixed-DPI virtual desktops, UAC elevation,
//! and games that reject synthetic input.

use std::{io, mem::size_of};

use erd_proto::input::{InputEvent, InputEventType, Modifiers};
use windows::Win32::{
    UI::{
        Input::KeyboardAndMouse::{
            SendInput, INPUT, INPUT_0, INPUT_KEYBOARD, INPUT_MOUSE, KEYBDINPUT,
            KEYBD_EVENT_FLAGS, KEYEVENTF_EXTENDEDKEY, KEYEVENTF_KEYUP, MOUSEEVENTF_ABSOLUTE,
            MOUSEEVENTF_HWHEEL, MOUSEEVENTF_LEFTDOWN, MOUSEEVENTF_LEFTUP, MOUSEEVENTF_MOVE,
            MOUSEEVENTF_RIGHTDOWN, MOUSEEVENTF_RIGHTUP, MOUSEEVENTF_VIRTUALDESK,
            MOUSEEVENTF_WHEEL, MOUSEINPUT, MOUSE_EVENT_FLAGS, VIRTUAL_KEY, VK_LCONTROL, VK_LMENU,
            VK_LSHIFT, VK_LWIN,
        },
        WindowsAndMessaging::{
            GetSystemMetrics, SM_CXVIRTUALSCREEN, SM_CYVIRTUALSCREEN, SM_XVIRTUALSCREEN,
            SM_YVIRTUALSCREEN,
        },
    },
};

const ABSOLUTE_AXIS_MAX: f64 = 65_535.0;
const WHEEL_DELTA: f32 = 120.0;

/// Windows virtual desktop bounds in physical pixels.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct VirtualDesktop {
    pub x: i32,
    pub y: i32,
    pub width: u32,
    pub height: u32,
}

/// Target display bounds within the virtual desktop.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TargetDisplay {
    pub x: i32,
    pub y: i32,
    pub width: u32,
    pub height: u32,
}

impl TargetDisplay {
    pub fn from_virtual_desktop(desktop: VirtualDesktop) -> Self {
        Self {
            x: desktop.x,
            y: desktop.y,
            width: desktop.width,
            height: desktop.height,
        }
    }
}

/// Maps normalized protocol coordinates into the Windows absolute-input range.
pub fn normalize_absolute_pointer(
    normalized_x: f32,
    normalized_y: f32,
    target: TargetDisplay,
    desktop: VirtualDesktop,
) -> (i32, i32) {
    if target.width == 0 || target.height == 0 || desktop.width <= 1 || desktop.height <= 1 {
        return (0, 0);
    }
    let local_x = finite_unit(normalized_x) * target.width.saturating_sub(1) as f64;
    let local_y = finite_unit(normalized_y) * target.height.saturating_sub(1) as f64;
    let desktop_x = (target.x as f64 + local_x - desktop.x as f64)
        .clamp(0.0, desktop.width.saturating_sub(1) as f64);
    let desktop_y = (target.y as f64 + local_y - desktop.y as f64)
        .clamp(0.0, desktop.height.saturating_sub(1) as f64);
    (
        (desktop_x * ABSOLUTE_AXIS_MAX / desktop.width.saturating_sub(1) as f64).round() as i32,
        (desktop_y * ABSOLUTE_AXIS_MAX / desktop.height.saturating_sub(1) as f64).round() as i32,
    )
}

fn finite_unit(value: f32) -> f64 {
    if value.is_finite() {
        value.clamp(0.0, 1.0) as f64
    } else {
        0.0
    }
}

/// Convert a Windows VK to the protocol's macOS physical-key code.
pub fn vk_to_macos_keycode(vk: u16) -> Option<u16> {
    KEY_MAP
        .iter()
        .find_map(|&(macos, windows)| (windows == vk).then_some(macos))
}

/// Convert a protocol/macOS physical-key code to a Windows VK.
pub fn macos_keycode_to_vk(key_code: u16) -> Option<u16> {
    KEY_MAP
        .iter()
        .find_map(|&(macos, windows)| (macos == key_code).then_some(windows))
}

/// Apple ANSI physical key codes mirrored to Win32 virtual keys.
const KEY_MAP: &[(u16, u16)] = &[
    (0, 0x41), (1, 0x53), (2, 0x44), (3, 0x46), (4, 0x48), (5, 0x47),
    (6, 0x5A), (7, 0x58), (8, 0x43), (9, 0x56), (11, 0x42), (12, 0x51),
