    (76, 0x0D), (78, 0x6D), (81, 0xBB), (82, 0x60), (83, 0x61), (84, 0x62),
    (85, 0x63), (86, 0x64), (87, 0x65), (88, 0x66), (89, 0x67), (91, 0x68),
    (92, 0x69), (96, 0x74), (97, 0x75), (98, 0x76), (99, 0x72), (100, 0x77),
    (101, 0x78), (103, 0x7A), (105, 0x7C), (106, 0x7F), (107, 0x7D),
    (109, 0x79), (111, 0x7B), (113, 0x7E), (114, 0x2D), (115, 0x24),
    (116, 0x21), (117, 0x2E), (118, 0x73), (119, 0x23), (120, 0x71),
