+    /// unavailable, or over the protocol's 4 KiB UTF-8 cap.
+    pub fn poll(&mut self) -> Result<Option<String>, ClipboardError> {
+        let Some(sequence) = sequence_number() else {
+            return Ok(None);
+        };
+        if !self.suppressor.observe_sequence(sequence) {
+            return Ok(None);
+        }
