#[cfg(target_os = "linux")]
pub mod audio_linux;
#[cfg(target_os = "linux")]
pub mod capture_linux;
pub mod capture_macos;
#[cfg(target_os = "windows")]
pub mod capture_windows;
#[cfg(target_os = "linux")]
pub mod clipboard_linux;
#[cfg(target_os = "windows")]
pub mod clipboard_windows;
#[cfg(target_os = "linux")]
pub mod encode_linux;
pub mod encode_vt;
#[cfg(target_os = "linux")]
pub mod inject_linux;
pub mod inject_macos;
#[cfg(target_os = "windows")]
pub mod inject_windows;
pub mod session;

#[cfg(target_os = "macos")]
pub use capture_macos::{CaptureConfig, CaptureEvent, CaptureFrame, DisplayInfo, ScreenCapture};
#[cfg(target_os = "macos")]
pub use encode_vt::{EncodedFrame, EncoderConfig, VideoToolboxEncoder};
#[cfg(target_os = "macos")]
pub use inject_macos::{accessibility_is_trusted, request_accessibility, InputInjector};
pub use session::{
    random_pin, ConsentPrompt, HostConfig, HostServer, PairingRecord, PairingStore, SessionState,
    TimestampStats,
};

use std::sync::mpsc;
use std::time::Instant;

use thiserror::Error;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct DisplayInfo {
    pub logical_width: u32,
    pub logical_height: u32,
    pub pixel_width: u32,
    pub pixel_height: u32,
    pub scale_factor_milli: u32,
}

impl DisplayInfo {
    pub fn scale_factor(self) -> f32 {
        self.scale_factor_milli as f32 / 1_000.0
    }
}

#[derive(Debug, Clone, Copy)]
pub struct CaptureConfig {
    pub width: u32,
    pub height: u32,
    /// Zero captures at the display's native refresh rate.
    pub frames_per_second: u32,
    pub capture_audio: bool,
}

impl CaptureConfig {
    pub fn native(display: DisplayInfo, capture_audio: bool) -> Self {
        Self {
            width: display.pixel_width,
            height: display.pixel_height,
            frames_per_second: 0,
            capture_audio,
        }
    }
}

#[derive(Debug)]
pub struct CaptureFrame {
    pub width: u32,
    pub height: u32,
    pub bytes_per_row: usize,
    pub bgra: Vec<u8>,
    pub captured_at: Instant,
}

#[derive(Debug)]
pub enum CaptureEvent {
    Video(CaptureFrame),
    /// ScreenCaptureKit is configured for 48 kHz stereo Float32 interleaved PCM.
    Audio {
        pcm_f32_le: Vec<u8>,
        captured_at: Instant,
    },
    Stopped(String),
}

#[derive(Debug, Error)]
pub enum CaptureError {
    #[error("ScreenCaptureKit is available only on macOS")]
    Unsupported,
    #[error("Screen Recording access is not granted")]
    PermissionDenied,
    #[error("no display is available")]
    NoDisplay,
    #[error("ScreenCaptureKit failed: {0}")]
    ScreenCaptureKit(String),
    #[error("capture setup timed out")]
    Timeout,
}

#[cfg(target_os = "macos")]
mod macos {
    use super::*;
    use block2::RcBlock;
    use core_graphics::display::CGDisplay;
    use objc2::ffi::NSInteger;
    use objc2::rc::Retained;
    use objc2::runtime::{AnyObject, NSObject, NSObjectProtocol, ProtocolObject};
    use objc2::{define_class, msg_send, AnyThread, DeclaredClass};
    use objc2_core_media::CMSampleBuffer;
    use objc2_core_video::{
        kCVPixelFormatType_32BGRA, CVPixelBufferGetBaseAddress, CVPixelBufferGetBytesPerRow,
        CVPixelBufferGetHeight, CVPixelBufferGetPixelFormatType, CVPixelBufferGetWidth,
        CVPixelBufferLockBaseAddress, CVPixelBufferLockFlags, CVPixelBufferUnlockBaseAddress,
    };
    use objc2_foundation::{NSArray, NSError};
    use objc2_screen_capture_kit::{
        SCContentFilter, SCShareableContent, SCStream, SCStreamConfiguration, SCStreamOutput,
        SCStreamOutputType,
    };
    use std::ptr;
    use std::sync::{Arc, Mutex};
    use std::time::Duration;

    extern "C" {
        fn CGPreflightScreenCaptureAccess() -> bool;
        fn CGRequestScreenCaptureAccess() -> bool;
    }

    struct SinkIvars {
        sender: Mutex<mpsc::Sender<CaptureEvent>>,
    }

    define_class!(
        #[unsafe(super(NSObject))]
        #[ivars = SinkIvars]
        struct FrameSink;

        unsafe impl NSObjectProtocol for FrameSink {}

        unsafe impl SCStreamOutput for FrameSink {
            #[unsafe(method(stream:didOutputSampleBuffer:ofType:))]
            unsafe fn __stream_did_output_sample_buffer_of_type(
                &self,
                _stream: *mut SCStream,
                sample_buffer: *mut AnyObject,
                output_type: NSInteger,
            ) {
                if sample_buffer.is_null() {
                    return;
                }
                let sample = &*(sample_buffer.cast::<CMSampleBuffer>());
                let event = if output_type == SCStreamOutputType::Screen.0 {
