            key_frame_interval: frames_per_second.max(1),
        }
    }

    pub fn lan(width: u32, height: u32, frames_per_second: u32, bitrate: u32) -> Self {
        Self {
            width,
            height,
            frames_per_second,
            bitrate: bitrate.clamp(MIN_LAN_BITRATE, MAX_LAN_BITRATE),
            key_frame_interval: frames_per_second.max(1),
